// Mechanical asset export only: all artwork is generated by image_gen, not drawn here.
const fs = require('node:fs');
const path = require('node:path');
const { createRequire } = require('node:module');
const runtime = process.env.CODEX_NODE_MODULES;
if (!runtime) throw new Error('Set CODEX_NODE_MODULES to the bundled node_modules directory');
const sharp = createRequire(path.join(runtime, '_accessory_export.cjs'))('sharp');
const root = path.resolve(__dirname, '..');
const out = path.join(root, 'art/accessories-draft-v1');
const manifest = JSON.parse(fs.readFileSync(path.join(out, 'manifest.json'), 'utf8'));
(async () => {
  for (const sub of ['originals', '16x16', 'previews']) fs.mkdirSync(path.join(out, sub), {recursive: true});
  const tiles = [];
  for (const [i, entry] of manifest.items.entries()) {
    const original = path.join(out, 'originals', entry.id + '.png');
    if (!fs.existsSync(original)) fs.copyFileSync(entry.source, original);
    const icon = path.join(out, '16x16', entry.id + '.png');
    // Preserve generated alpha and silhouette. No recolouring or hand-authored substitute.
    await sharp(original).resize(16, 16, {kernel: 'nearest', fit: 'contain', background: '#00000000'}).png().toFile(icon);
    const meta = await sharp(icon).metadata();
    if (meta.width !== 16 || meta.height !== 16 || !meta.hasAlpha) throw new Error('Invalid sprite: ' + entry.id);
    const enlarged = await sharp(icon).resize(128,128,{kernel:'nearest'}).png().toBuffer();
    await fs.promises.writeFile(path.join(out, 'previews', entry.id + '.png'), enlarged);
    tiles.push({input: enlarged, left: 16 + (i%4)*160, top: 16+Math.floor(i/4)*176});
    const label = Buffer.from('<svg width="160" height="28"><text x="80" y="20" text-anchor="middle" fill="#eee" font-size="15" font-family="Microsoft YaHei">' + entry.name + '</text></svg>');
    tiles.push({input:label,left:(i%4)*160,top:148+Math.floor(i/4)*176});
    for (const loader of ['forge-1.20.1','neoforge-1.21.1']) {
      const target = path.join(root,loader,'src/main/resources/assets/laowu/textures/item',entry.id+'.png');
      if (fs.existsSync(target) && !fs.readFileSync(target).equals(fs.readFileSync(icon)))
        throw new Error('Refusing to overwrite edited accessory art: ' + target);
      fs.copyFileSync(icon,target);
    }
    console.log('Exported 16x16 RGBA: ' + entry.id);
  }
  await sharp({create:{width:640,height:704,channels:4,background:'#292730'}}).composite(tiles).png().toFile(path.join(out,'contact-sheet.png'));
})().catch(e=>{console.error(e);process.exitCode=1;});
